package com.quicknotes.app;
import org.json.*;import java.util.*;
/** Shared calendar rules used by notification completion and UI recurrence. */
final class Repeats {
 static long next(JSONObject i,long now)throws Exception{long due=i.optLong("due");String repeat=i.optString("repeat");if(due<=0||repeat.isEmpty())return 0;JSONObject rule=i.optJSONObject("repeatRule");if(rule==null)rule=new JSONObject();String f="custom".equals(repeat)?rule.optString("frequency","weekly"):repeat;int interval=Math.max(1,Math.min(999,rule.optInt("interval",1)));long after=Math.max(due,now);if(f.equals("hourly"))return due+((after-due)/(3600000L*interval)+1)*3600000L*interval;
 Calendar base=Calendar.getInstance(),d=Calendar.getInstance();base.setTimeInMillis(due);d.setTimeInMillis(due);int startMonth=base.get(Calendar.YEAR)*12+base.get(Calendar.MONTH);JSONArray days=rule.optJSONArray("days"),monthDays=rule.optJSONArray("monthDays");int baseDay=base.get(Calendar.DAY_OF_WEEK)-1;
 for(int n=1;n<=366000;n++){d.add(Calendar.DATE,1);if(d.getTimeInMillis()<=after)continue;int day=d.get(Calendar.DAY_OF_WEEK)-1,months=d.get(Calendar.YEAR)*12+d.get(Calendar.MONTH)-startMonth;boolean ok=false;
 if(f.equals("daily"))ok=n%interval==0;else if(f.equals("weekdays"))ok=day>0&&day<6;else if(f.equals("weekends"))ok=day==0||day==6;else if(f.equals("weekly"))ok=(n/7)%interval==0&&(days!=null&&days.length()>0?contains(days,day):day==baseDay);else if(f.equals("monthly")||f.equals("yearly")){int period=f.equals("yearly")?interval*12:interval;ok=(repeat.equals("custom")?months>=0:months>0)&&months%period==0;if(ok&&repeat.equals("custom")&&rule.optString("mode").equals("ordinal")){int ordinal=rule.optInt("ordinal",1);ok=day==rule.optInt("weekday")&&(ordinal==-1?d.get(Calendar.DATE)+7>d.getActualMaximum(Calendar.DATE):(d.get(Calendar.DATE)+6)/7==ordinal);}else if(ok&&repeat.equals("custom")&&monthDays!=null&&monthDays.length()>0)ok=contains(monthDays,d.get(Calendar.DATE));else if(ok)ok=d.get(Calendar.DATE)==Math.min(base.get(Calendar.DATE),d.getActualMaximum(Calendar.DATE));}if(ok)return d.getTimeInMillis();}return 0;}
 static boolean contains(JSONArray a,int v){for(int n=0;n<a.length();n++)if(a.optInt(n)==v)return true;return false;}
 static void complete(JSONObject d,String id,long now)throws Exception{JSONObject i=Reminders.find(d,id);if(i==null||i.optBoolean("done")||i.optBoolean("deleted"))return;i.put("done",true).put("completedAt",now).put("updated",Math.max(now,i.optLong("updated")+1));spawn(d,i,now);i.put("nextDue",0);markChildren(d,id,now);}
 static void markChildren(JSONObject d,String id,long now)throws Exception{JSONArray a=d.getJSONArray("items");for(int n=0;n<a.length();n++){JSONObject c=a.getJSONObject(n);if(id.equals(c.optString("parent"))&&!c.optBoolean("deleted")){c.put("done",true).put("completedAt",now).put("updated",Math.max(now,c.optLong("updated")+1));markChildren(d,c.getString("id"),now);}}}
 static void spawn(JSONObject d,JSONObject i,long now)throws Exception{if(i.optString("repeat").isEmpty()||i.optLong("due")==0)return;long due=i.optLong("nextDue");if(due==0)due=next(i,now);if(due==0)return;String series=i.optString("seriesId",i.getString("id")),id=series+"-r-"+Long.toString(due,36);if(Reminders.find(d,id)!=null)return;JSONObject next=new JSONObject(i.toString());next.put("id",id).put("seriesId",series).put("due",due).put("done",false).put("completedAt",0).put("nextDue",0).put("updated",now).put("order",i.optDouble("order",0)+.1);next.remove("nextId");d.getJSONArray("items").put(next);i.put("nextId",id);cloneChildren(d,i.getString("id"),id,due,now);}
 static void cloneChildren(JSONObject d,String old,String parent,long due,long now)throws Exception{JSONArray a=d.getJSONArray("items");int length=a.length();for(int n=0;n<length;n++){JSONObject c=a.getJSONObject(n);if(old.equals(c.optString("parent"))&&!c.optBoolean("deleted")){String series=c.optString("seriesId",c.getString("id")),cid=series+"-r-"+Long.toString(due,36);if(Reminders.find(d,cid)==null){JSONObject copy=new JSONObject(c.toString());copy.put("id",cid).put("seriesId",series).put("parent",parent).put("done",false).put("completedAt",0).put("nextDue",0).put("updated",now);a.put(copy);cloneChildren(d,c.getString("id"),cid,due,now);}}}}
 static boolean migrate(JSONObject d,long now)throws Exception{boolean changed=false;JSONArray a=d.getJSONArray("items");int length=a.length();for(int n=0;n<length;n++){JSONObject i=a.getJSONObject(n);if(i.optBoolean("done")&&!i.optBoolean("deleted")&&i.optLong("nextDue")>0){spawn(d,i,now);i.put("nextDue",0).put("updated",Math.max(now,i.optLong("updated")+1));changed=true;}}return changed;}
}
